// Process session creation request
const sessionData = $input.first().json;
const { 
  userId, 
  campaignId, 
  sessionName, 
  maxPlayers = 6, 
  sessionType = 'campaign',
  settings = {} 
} = sessionData;

// Validate required fields
if (!userId || !campaignId || !sessionName) {
  throw new Error('Missing required fields: userId, campaignId, sessionName');
}

// Generate session ID
const sessionId = `session_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`;

// Session configuration
const sessionConfig = {
  sessionId,
  userId,
  campaignId,
  sessionName,
  sessionType, // 'campaign', 'one-shot', 'tutorial', 'testing'
  maxPlayers,
  currentPlayers: 0,
  status: 'preparing',
  createdAt: new Date().toISOString(),
  settings: {
    voiceChat: settings.voiceChat || true,
    videoChat: settings.videoChat || false,
    screenShare: settings.screenShare || true,
    autoSave: settings.autoSave || true,
    saveInterval: settings.saveInterval || 300, // 5 minutes
    ...settings
  },
  resourceAllocation: {
    maxMemory: '512MB',
    maxCpu: '0.5',
    maxBandwidth: '1Mbps',
    aiAgentSlots: 2,
    voiceChannels: 1
  },
  metadata: {
    createdBy: userId,
    createdWith: 'n8n-workflow',
    version: '1.0'
  }
};

return { json: sessionConfig };

// Allocate system resources for the session
const sessionData = $input.first().json;
const { sessionId, resourceAllocation } = sessionData;

// Create resource allocation record
const resourceRecord = {
  sessionId,
  allocatedAt: new Date().toISOString(),
  resources: {
    memory: {
      allocated: resourceAllocation.maxMemory,
      used: '0MB',
      peak: '0MB'
    },
    cpu: {
      allocated: resourceAllocation.maxCpu,
      current: '0.0',
      peak: '0.0'
    },
    bandwidth: {
      allocated: resourceAllocation.maxBandwidth,
      current: '0bps',
      peak: '0bps'
    },
    aiAgents: {
      allocated: resourceAllocation.aiAgentSlots,
      active: 0,
      available: resourceAllocation.aiAgentSlots
    },
    voiceChannels: {
      allocated: resourceAllocation.voiceChannels,
      active: 0
    }
  },
  status: 'allocated'
};

return { json: resourceRecord };

// Initialize session state and game state
const sessionData = $input.first().json;
const { sessionId, userId, campaignId } = sessionData;

// Create initial session state
const sessionState = {
  sessionId,
  gameMasterId: userId,
  campaignId,
  state: {
    phase: 'setup', // 'setup', 'active', 'paused', 'ended'
    turnOrder: [],
    currentTurn: null,
    roundNumber: 0,
    initiativeTracker: {
      currentRound: 0,
      turnIndex: 0,
      participants: []
    }
  },
  gameState: {
    scene: {
      name: 'Starting Scene',
      description: '',
      environment: 'unknown',
      lighting: 'normal',
      weather: 'clear'
    },
    parties: [
      {
        id: 'player_party',
        name: 'Player Party',
        members: [],
        position: { x: 0, y: 0 }
      }
    ],
    npcs: [],
    enemies: [],
    objects: [],
    map: {
      grid: null,
      size: { width: 0, height: 0 },
      scale: '5ft'
    },
    combat: {
      active: false,
      startedAt: null,
      currentRound: 0
    }
  },
  lastUpdated: new Date().toISOString()
};

return { json: sessionState };

// Setup session monitoring and health checks
const sessionData = $input.first().json;
const { sessionId } = sessionData;

// Create monitoring configuration
const monitoringConfig = {
  sessionId,
  healthChecks: {
    connectionHealth: {
      enabled: true,
      interval: 30, // seconds
      timeout: 10,
      maxFailures: 3
    },
    resourceHealth: {
      enabled: true,
      interval: 60, // seconds
      memoryThreshold: 0.9, // 90%
      cpuThreshold: 0.8, // 80%
      bandwidthThreshold: 0.9 // 90%
    },
    performanceHealth: {
      enabled: true,
      interval: 120, // seconds
      latencyThreshold: 1000, // ms
      errorRateThreshold: 0.05 // 5%
    }
  },
  alerts: {
    email: true,
    webhook: true,
    slack: false
  },
  metrics: {
    playerCount: 0,
    messageCount: 0,
    averageLatency: 0,
    errorRate: 0,
    uptime: 0
  },
  createdAt: new Date().toISOString()
};

return { json: monitoringConfig };

// Process session join request
const joinData = $input.first().json;
const { sessionId, userId, characterId, joinAs = 'player' } = joinData;

// Validate required fields
if (!sessionId || !userId || !characterId) {
  throw new Error('Missing required fields: sessionId, userId, characterId');
}

// Get session information
const sessionInfo = await $getGoogleFirestoreItem('game_sessions', sessionId);
if (!sessionInfo) {
  throw new Error('Session not found');
}

// Check if session is joinable
if (sessionInfo.status !== 'preparing' && sessionInfo.status !== 'active') {
  throw new Error('Session is not accepting new players');
}

// Check player limit
if (sessionInfo.currentPlayers >= sessionInfo.maxPlayers) {
  throw new Error('Session is full');
}

// Check if user is already in session
const existingPlayer = sessionInfo.players?.find(p => p.userId === userId);
if (existingPlayer) {
  throw new Error('User already in session');
}

return {
  json: {
    sessionId,
    userId,
    characterId,
    joinAs,
    sessionInfo
  }
};

// Add player to session and update counters
const joinData = $input.first().json;
const { sessionId, userId, characterId, joinAs, sessionInfo } = joinData;

// Create player record
const playerRecord = {
  userId,
  characterId,
  joinAs,
  joinedAt: new Date().toISOString(),
  status: 'connected',
  role: joinAs === 'dm' ? 'game_master' : 'player',
  permissions: {
    canControlNpcs: joinAs === 'dm',
    canEditMap: joinAs === 'dm',
    canRollDice: true,
    canUseVoice: sessionInfo.settings.voiceChat,
    canUseVideo: sessionInfo.settings.videoChat
  }
};

// Update session players
const currentPlayers = sessionInfo.players || [];
const updatedPlayers = [...currentPlayers, playerRecord];

// Update session record
const sessionUpdates = {
  players: updatedPlayers,
  currentPlayers: updatedPlayers.length,
  lastActivity: new Date().toISOString(),
  status: updatedPlayers.length > 0 ? 'active' : 'preparing'
};

// Check if session should auto-start
if (updatedPlayers.length >= 2 && sessionInfo.status === 'preparing') {
  sessionUpdates.status = 'active';
  sessionUpdates.startedAt = new Date().toISOString();
}

return {
  json: {
    sessionId,
    playerRecord,
    sessionUpdates,
    totalPlayers: updatedPlayers.length
  }
};

// Allocate player-specific resources
const joinData = $input.first().json;
const { sessionId, playerRecord } = joinData;

// Get current resource allocation
const resourceRecord = await $getGoogleFirestoreItem('session_resources', sessionId);
const resources = resourceRecord.resources;

// Allocate player resources
const playerResources = {
  memory: '64MB',
  cpu: '0.1',
  bandwidth: '100kbps',
  voiceChannel: playerRecord.permissions.canUseVoice ? 1 : 0,
  aiAgentSlots: joinData.joinAs === 'dm' ? 1 : 0
};

// Update resource allocation
const updatedResources = {
  ...resources,
  memory: {
    ...resources.memory,
    used: incrementMemory(resources.memory.used, playerResources.memory)
  },
  cpu: {
    ...resources.cpu,
    current: (parseFloat(resources.cpu.current) + parseFloat(playerResources.cpu)).toString()
  },
  bandwidth: {
    ...resources.bandwidth,
    current: incrementBandwidth(resources.bandwidth.current, playerResources.bandwidth)
  },
  voiceChannels: {
    ...resources.voiceChannels,
    active: resources.voiceChannels.active + playerResources.voiceChannel
  },
  aiAgents: {
    ...resources.aiAgents,
    active: resources.aiAgents.active + playerResources.aiAgentSlots
  }
};

function incrementMemory(current, addition) {
  const currentMB = parseInt(current.replace('MB', ''));
  const additionMB = parseInt(addition.replace('MB', ''));
  return `${currentMB + additionMB}MB`;
}

function incrementBandwidth(current, addition) {
  const currentBps = parseBandwidth(current);
  const additionBps = parseBandwidth(addition);
  return formatBandwidth(currentBps + additionBps);
}

function parseBandwidth(bandwidth) {
  const value = parseInt(bandwidth);
  if (bandwidth.includes('Mbps')) return value * 1000000;
  if (bandwidth.includes('kbps')) return value * 1000;
  return value;
}

function formatBandwidth(bps) {
  if (bps >= 1000000) return `${(bps / 1000000).toFixed(2)}Mbps`;
  if (bps >= 1000) return `${(bps / 1000).toFixed(0)}kbps`;
  return `${bps}bps`;
}

return {
  json: {
    sessionId,
    playerRecord,
    playerResources,
    updatedResources
  }
};

// Create player session state
const joinData = $input.first().json;
const { sessionId, playerRecord } = joinData;

// Get session state
const sessionState = await $getGoogleFirestoreItem('session_states', sessionId);

// Create player state
const playerState = {
  userId: playerRecord.userId,
  characterId: playerRecord.characterId,
  role: playerRecord.role,
  status: 'active',
  joinedAt: playerRecord.joinedAt,
  permissions: playerRecord.permissions,
  gameState: {
    position: { x: 0, y: 0 },
    health: { current: 100, max: 100 },
    resources: {
      actions: 1,
      bonusAction: 1,
      movement: 30,
      reaction: 1
    },
    conditions: [],
    inventory: [],
    spells: [],
    features: []
  },
  clientState: {
    viewport: { x: 0, y: 0, zoom: 1.0 },
    selectedCharacter: null,
    activeTools: [],
    uiState: 'normal'
  }
};

// Update session state with new player
if (!sessionState.players) {
  sessionState.players = [];
}
sessionState.players.push(playerState);

// Add to initiative tracker if needed
if (sessionState.gameState.combat.active) {
  sessionState.state.initiativeTracker.participants.push({
    id: playerRecord.characterId,
    name: playerRecord.characterId,
    initiative: Math.floor(Math.random() * 20) + 1,
    type: 'player'
  });
}

return {
  json: {
    sessionId,
    playerState,
    sessionState
  }
};

// Process session migration request
const migrateData = $input.first().json;
const { sessionId, targetServer, reason = 'load_balancing' } = migrateData;

// Validate required fields
if (!sessionId || !targetServer) {
  throw new Error('Missing required fields: sessionId, targetServer');
}

// Get session information
const sessionInfo = await $getGoogleFirestoreItem('game_sessions', sessionId);
if (!sessionInfo) {
  throw new Error('Session not found');
}

// Check if migration is allowed
if (sessionInfo.status === 'migrating') {
  throw new Error('Session already migrating');
}

if (sessionInfo.status === 'active' && sessionInfo.currentPlayers > 0) {
  // Active sessions require careful handling
  const canMigrate = await checkMigrationSafety(sessionId);
  if (!canMigrate) {
    throw new Error('Session not safe for migration (active combat/time-sensitive actions)');
  }
}

return {
  json: {
    sessionId,
    targetServer,
    reason,
    sessionInfo,
    migrationStarted: new Date().toISOString()
  }
};

async function checkMigrationSafety(sessionId) {
  // Check for active combat
  const sessionState = await $getGoogleFirestoreItem('session_states', sessionId);
  if (sessionState?.gameState?.combat?.active) {
    return false;
  }

  // Check for recent actions (within last 30 seconds)
  const recentActions = await checkRecentActivity(sessionId, 30);
  if (recentActions > 5) {
    return false;
  }

  return true;
}

async function checkRecentActivity(sessionId, seconds) {
